     1→import React from 'react';
     2→import { Card, Button, Badge, Spinner } from 'react-bootstrap';
     3→import './TemplateList.css';
     4→
     5→const TemplateList = ({ templates, loading, onEdit, onDelete }) => {
     6→  const getStatusBadge = (status) => {
     7→    const statusConfig = {
     8→      pending: { bg: '#FDD8D8', color: '#7D1E1E', text: 'En revisión por meta' },
     9→      approved: { bg: '#D4EDDA', color: '#155724', text: 'Aprobada' },
    10→      rejected: { bg: '#F8D7DA', color: '#721C24', text: 'Rechazada' },
    11→      draft: { bg: '#D1ECF1', color: '#0C5460', text: 'Borrador' }
    12→    };
    13→
    14→    const config = statusConfig[status] || statusConfig.draft;
    15→
    16→    return (
    17→      <Badge
    18→        className="template-status-badge"
    19→        style={{
    20→          backgroundColor: config.bg,
    21→          color: config.color
    22→        }}
    23→      >
    24→        {config.text}
