   424→      if (emojiPickerRef.current && !emojiPickerRef.current.contains(event.target)) {
   425→        setShowEmojiPicker(false);
   426→      }
   427→    };
   428→
   429→    if (showEmojiPicker) {
   430→      document.addEventListener('mousedown', handleClickOutside);
   431→    }
   432→
   433→    return () => {
   434→      document.removeEventListener('mousedown', handleClickOutside);
   435→    };
   436→  }, [showEmojiPicker]);
   437→
   438→  // Parsear formato de WhatsApp para vista previa
   439→  const parseWhatsAppFormatting = useCallback((text) => {
   440→    if (!text) return null;
   441→
   442→    // Escapar HTML primero
   443→    let html = text
   444→      .replace(/&/g, '&amp;')
   445→      .replace(/</g, '&lt;')
   446→      .replace(/>/g, '&gt;');
   447→
   448→    // Aplicar formato de código primero (```texto```)
   449→    html = html.replace(/```([^`]+)```/g, '<code class="wa-code">$1</code>');
   450→
   451→    // Negrita (*texto*)
   452→    html = html.replace(/\*([^*]+)\*/g, '<strong class="wa-bold">$1</strong>');
   453→
   454→    // Cursiva (_texto_)
   455→    html = html.replace(/_([^_]+)_/g, '<em class="wa-italic">$1</em>');
   456→
   457→    // Tachado (~texto~)
   458→    html = html.replace(/~([^~]+)~/g, '<del class="wa-strikethrough">$1</del>');
   459→
   460→    // Reemplazar variables {{1}}, {{2}}, etc. con estilo
   461→    html = html.replace(/\{\{(\d+)\}\}/g, '<span class="wa-variable">{{$1}}</span>');
   462→
   463→    // Preservar saltos de línea
   464→    html = html.replace(/\n/g, '<br />');
   465→
   466→    return html;
   467→  }, []);
   468→
   469→  return (
