import React, { useEffect, useState } from 'react';
import { Container, Row, Col, Button, Form, Modal, Alert } from 'react-bootstrap';
import TemplateForm from '../../components/templates/TemplateForm';
import TemplateList from '../../components/templates/TemplateList';
import useTemplatesStore from '../../store/templatesStore';
import useLinesStore from '../../store/linesStore';
import useAuthStore from '../../store/authStore';
import templateService from '../../services/templateService';
import lineService from '../../services/lineService';
import './Templates.css';

const Templates = () => {
  const {
    templates,
    loading,
    error,
    filters,
    setTemplates,
    setLoading,
    setError,
    addTemplate,
    updateTemplate,
    removeTemplate,
    setFilters
  } = useTemplatesStore();

  const { lines, setLines } = useLinesStore();
  const { user } = useAuthStore();

  // Check if user can manage templates (admin or manager)
  const canManageTemplates = user?.role === 'admin' || user?.role === 'manager';

  const [showForm, setShowForm] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [templateToDelete, setTemplateToDelete] = useState(null);
  const [successMessage, setSuccessMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);

  useEffect(() => {
    loadTemplates();
    loadLines();
  }, [filters]);

  const loadTemplates = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await templateService.getTemplates(filters);
      setTemplates(response.data.templates);
    } catch (err) {
      console.error('Error loading templates:', err);
      setError('Error al cargar las plantillas');
    } finally {
      setLoading(false);
    }
  };

  const loadLines = async () => {
    try {
      if (lines.length === 0) {
        const linesResponse = await lineService.getLines();
        setLines(linesResponse.data);
      }
    } catch (err) {
      console.error('Error loading lines:', err);
    }
  };

  const handleCreateTemplate = async (formData) => {
    setFormLoading(true);
    try {
      const response = await templateService.createTemplate({
        ...formData,
        submitToMeta: true
      });

      if (response.success) {
        addTemplate(response.data);
        setSuccessMessage('Plantilla creada y enviada a Meta para aprobación');
        setTimeout(() => setSuccessMessage(''), 5000);
      }
    } catch (err) {
      console.error('Error creating template:', err);
      setError('Error al crear la plantilla');
    } finally {
      setFormLoading(false);
    }
  };

  const handleUpdateTemplate = async (formData) => {
    if (!editingTemplate) return;

    setFormLoading(true);
    try {
      const response = await templateService.updateTemplate(
        editingTemplate.id,
        formData,
        true // submitToMeta
      );

      if (response.success) {
        updateTemplate(editingTemplate.id, response.data);
        setSuccessMessage('Plantilla actualizada y enviada a Meta para aprobación');
        setTimeout(() => setSuccessMessage(''), 5000);
      }
    } catch (err) {
      console.error('Error updating template:', err);
      setError('Error al actualizar la plantilla');
    } finally {
      setFormLoading(false);
    }
  };

  const handleFormSubmit = async (formData) => {
    if (editingTemplate) {
      await handleUpdateTemplate(formData);
    } else {
      await handleCreateTemplate(formData);
    }
  };

  const handleEdit = (template) => {
    setEditingTemplate(template);
    setShowForm(true);
  };

  const handleDelete = (template) => {
    setTemplateToDelete(template);
    setShowDeleteModal(true);
  };

  const confirmDelete = async () => {
    if (!templateToDelete) return;

    try {
      await templateService.deleteTemplate(templateToDelete.id);
      removeTemplate(templateToDelete.id);
      setSuccessMessage('Plantilla eliminada correctamente');
      setTimeout(() => setSuccessMessage(''), 5000);
      setShowDeleteModal(false);
      setTemplateToDelete(null);
    } catch (err) {
      console.error('Error deleting template:', err);
      setError('Error al eliminar la plantilla');
      setShowDeleteModal(false);
    }
  };

  const handleCloseForm = () => {
    setShowForm(false);
    setEditingTemplate(null);
  };

  const handleFilterChange = (filterKey, value) => {
    setFilters({ [filterKey]: value || null });
  };

  return (
    <Container fluid className="templates-page">
      <Row className="templates-header">
        <Col>
          <div className="templates-header-content">
            <div>
              <h1 className="templates-title">
                Plantillas agregadas ({templates.length})
              </h1>
              <p className="templates-subtitle">
                Gestiona las plantillas de mensajes para WhatsApp
              </p>
            </div>
            {canManageTemplates && (
              <Button
                variant="primary"
                className="templates-add-btn"
                onClick={() => setShowForm(true)}
              >
                Agregar plantilla
                <i className="bi bi-plus-lg ms-2"></i>
              </Button>
            )}
          </div>
        </Col>
      </Row>

      {successMessage && (
        <Row className="mt-3">
          <Col>
            <Alert variant="success" onClose={() => setSuccessMessage('')} dismissible>
              {successMessage}
            </Alert>
          </Col>
        </Row>
      )}

      {error && (
        <Row className="mt-3">
          <Col>
            <Alert variant="danger" onClose={() => setError(null)} dismissible>
              {error}
            </Alert>
          </Col>
        </Row>
      )}

      <Row className="templates-filters">
        <Col md={4}>
          <Form.Group>
            <Form.Label className="templates-filter-label">Filtrar por línea</Form.Label>
            <Form.Select
              value={filters.lineId || ''}
              onChange={(e) => handleFilterChange('lineId', e.target.value)}
              className="templates-filter-select"
            >
              <option value="">Todas las líneas</option>
              {lines.map(line => (
                <option key={line.id} value={line.id}>
                  {line.company_name} - {line.phone_number}
                </option>
              ))}
            </Form.Select>
          </Form.Group>
        </Col>
        <Col md={4}>
          <Form.Group>
            <Form.Label className="templates-filter-label">Filtrar por estado</Form.Label>
            <Form.Select
              value={filters.status || ''}
              onChange={(e) => handleFilterChange('status', e.target.value)}
              className="templates-filter-select"
            >
              <option value="">Todos los estados</option>
              <option value="draft">Borrador</option>
              <option value="pending">En revisión</option>
              <option value="approved">Aprobada</option>
              <option value="rejected">Rechazada</option>
            </Form.Select>
          </Form.Group>
        </Col>
      </Row>

      <Row className="templates-content">
        <Col>
          <TemplateList
            templates={templates}
            loading={loading}
            onEdit={canManageTemplates ? handleEdit : null}
            onDelete={canManageTemplates ? handleDelete : null}
          />
        </Col>
      </Row>

      <TemplateForm
        show={showForm}
        onHide={handleCloseForm}
        onSubmit={handleFormSubmit}
        template={editingTemplate}
        lines={lines}
        loading={formLoading}
      />

      <Modal
        show={showDeleteModal}
        onHide={() => setShowDeleteModal(false)}
        scrollable
        className="template-delete-modal"
      >
        <Modal.Header closeButton>
          <Modal.Title>Confirmar eliminación</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>
            ¿Estás seguro de que deseas eliminar la plantilla{' '}
            <strong>{templateToDelete?.name}</strong>?
          </p>
          <p className="text-muted">Esta acción no se puede deshacer.</p>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="outline-dark"
            onClick={() => setShowDeleteModal(false)}
          >
            Cancelar
          </Button>
          <Button variant="danger" onClick={confirmDelete}>
            Eliminar
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default Templates;

