import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Form, Button, Row, Col, Tabs, Tab, Card, Spinner, Alert } from 'react-bootstrap';
import EmojiPicker from 'emoji-picker-react';
import ButtonEditor from './ButtonEditor';
import templateService from '../../services/templateService';
import './TemplateForm.css';

const snakeCaseRegex = /^[a-z0-9]+(?:_[a-z0-9]+)*$/;

const TemplateForm = ({ show, onHide, onSubmit, template = null, lines = [], loading = false }) => {
  const contentTextareaRef = useRef(null);
  const [formData, setFormData] = useState({
    name: '',
    lineId: '',
    content: '',
    variables: [],
    category: 'UTILITY',
    language: 'es',
    headerType: 'NONE',
    headerContent: '',
    headerExample: null,
    headerFilename: '',
    footerText: '',
    buttons: []
  });
  const [charCount, setCharCount] = useState(0);
  const [headerCharCount, setHeaderCharCount] = useState(0);
  const [footerCharCount, setFooterCharCount] = useState(0);
  const [errors, setErrors] = useState({});
  const [activeTab, setActiveTab] = useState('body');
  const [uploadingFile, setUploadingFile] = useState(false);
  const [uploadedFile, setUploadedFile] = useState(null);
  const [uploadError, setUploadError] = useState(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const emojiPickerRef = useRef(null);

  // Calcular el conteo de caracteres del body con las variables reemplazadas
  const calculateBodyCharCount = useCallback((content, variables) => {
    let finalContent = content;

    // Reemplazar cada variable {{1}}, {{2}}, etc. con su valor de ejemplo
    variables.forEach((variable, index) => {
      const placeholder = `{{${index + 1}}}`;
      const exampleValue = variable.example || '';
      finalContent = finalContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), exampleValue);
    });

    return finalContent.length;
  }, []);

  useEffect(() => {
    if (template) {
      const parsedVariables = template.variables ?
        (typeof template.variables === 'string' ? JSON.parse(template.variables) : template.variables)
        : [];
      const parsedButtons = template.buttons ?
        (typeof template.buttons === 'string' ? JSON.parse(template.buttons) : template.buttons)
        : [];

      setFormData({
        name: template.name || '',
        lineId: template.line_id || '',
        content: template.content || '',
        variables: parsedVariables,
        category: template.category || 'UTILITY',
        language: template.language || 'es',
        headerType: template.header_type || 'NONE',
        headerContent: template.header_content || '',
        headerExample: template.header_example || null,
        headerCaption: template.header_caption || '',
        headerFilename: template.header_filename || '',
        footerText: template.footer_text || '',
        buttons: parsedButtons
      });
      setCharCount(calculateBodyCharCount(template.content || '', parsedVariables));
      setHeaderCharCount(template.header_content?.length || 0);
      setFooterCharCount(template.footer_text?.length || 0);
    } else {
      setFormData({
        name: '',
        lineId: '',
        content: '',
        variables: [],
        category: 'UTILITY',
        language: 'es',
        headerType: 'NONE',
        headerContent: '',
        headerExample: null,
        headerCaption: '',
        headerFilename: '',
        footerText: '',
        buttons: []
      });
      setCharCount(0);
      setHeaderCharCount(0);
      setFooterCharCount(0);
    }
    // Limpiar archivo subido al abrir/cerrar
    setUploadedFile(null);
    setUploadError(null);
  }, [template, show]);

  // Limpiar archivo subido cuando cambia el tipo de header
  useEffect(() => {
    if (!['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType)) {
      setUploadedFile(null);
      setUploadError(null);
    }
  }, [formData.headerType]);

  const handleContentChange = (e) => {
    const content = e.target.value;
    setFormData({ ...formData, content });
    setCharCount(calculateBodyCharCount(content, formData.variables));
  };

  const handleVariableChange = (index, field, value) => {
    const newVariables = [...formData.variables];
    newVariables[index] = { ...newVariables[index], [field]: value };
    setFormData({ ...formData, variables: newVariables });

    // Recalcular el contador si cambió el ejemplo de la variable
    if (field === 'example') {
      setCharCount(calculateBodyCharCount(formData.content, newVariables));
    }
  };

  const addVariable = () => {
    const newVariables = [...formData.variables, { name: '', type: 'text', example: '' }];
    setFormData({ ...formData, variables: newVariables });
    setCharCount(calculateBodyCharCount(formData.content, newVariables));
  };

  const removeVariable = (index) => {
    const newVariables = formData.variables.filter((_, i) => i !== index);
    setFormData({ ...formData, variables: newVariables });
    setCharCount(calculateBodyCharCount(formData.content, newVariables));
  };

  const handleHeaderChange = (e) => {
    const headerContent = e.target.value;

    // Si es tipo TEXT, solo actualizar el contenido
    if (formData.headerType === 'TEXT') {
      setFormData({ ...formData, headerContent });
      setHeaderCharCount(headerContent.length);
    } else if (['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType)) {
      // Si es tipo media y se ingresa manualmente una URL pública
      const newFormData = { ...formData, headerContent };
      if (headerContent.trim()) {
        // Para URLs manuales, usarlas tanto en headerContent como en header_example
        newFormData.headerExample = {
          header_handle: [headerContent]
        };
      } else {
        newFormData.headerExample = null;
      }
      setFormData(newFormData);
    } else {
      setFormData({ ...formData, headerContent });
    }
  };

  const handleFooterChange = (e) => {
    const footerText = e.target.value;
    setFormData({ ...formData, footerText });
    setFooterCharCount(footerText.length);
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validar que se haya seleccionado una linea
    if (!formData.lineId) {
      setUploadError('Debe seleccionar una linea de WhatsApp antes de subir archivos');
      e.target.value = '';
      return;
    }

    setUploadingFile(true);
    setUploadError(null);

    try {
      // Determinar tipo de media
      let mediaType;
      if (formData.headerType === 'IMAGE') {
        mediaType = 'image';
      } else if (formData.headerType === 'VIDEO') {
        mediaType = 'video';
      } else if (formData.headerType === 'DOCUMENT') {
        mediaType = 'document';
      }

      // Subir el archivo usando el servicio específico para templates
      const uploadResult = await templateService.uploadMediaForTemplate(
        file,
        formData.lineId,
        mediaType
      );

      // Guardar el archivo subido
      setUploadedFile({
        filename: uploadResult.filename || uploadResult.originalName,
        handle: uploadResult.handle,
        publicUrl: uploadResult.publicUrl,
        mimeType: uploadResult.mimeType,
        size: uploadResult.size,
        originalName: uploadResult.originalName || file.name
      });

      // Para templates:
      // - headerContent: usar publicUrl (para enviar mensajes)
      // - header_example.header_handle: usar handle de Meta (para crear la plantilla)
      // - headerFilename: nombre original del archivo (para documentos)
      const publicUrl = uploadResult.publicUrl;
      const handle = uploadResult.handle || uploadResult.publicUrl;

      setFormData({
        ...formData,
        headerContent: publicUrl,
        headerExample: {
          header_handle: [handle]
        },
        headerFilename: mediaType === 'document' ? uploadResult.filename : ''
      });
    } catch (error) {
      console.error('Error uploading file:', error);
      setUploadError(error.response?.data?.message || 'Error al subir el archivo');
      e.target.value = '';
    } finally {
      setUploadingFile(false);
    }
  };

  const handleRemoveFile = () => {
    setUploadedFile(null);
    setFormData({ ...formData, headerContent: '', headerExample: null, headerFilename: '' });
    setUploadError(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validacion
    const newErrors = {};
    if (!formData.name) {
      newErrors.name = 'El nombre es obligatorio';
    } else if (!snakeCaseRegex.test(formData.name)) {
      newErrors.name = 'Usa formato snake_case: solo minusculas, numeros y guiones bajos';
    }
    if (!formData.lineId) newErrors.lineId = 'Debe seleccionar una linea';
    if (!formData.content.trim()) newErrors.content = 'El contenido es requerido';
    if (charCount > 1024) newErrors.content = 'El contenido con variables excede 1024 caracteres';

    // Validar header
    if (formData.headerType === 'TEXT' && formData.headerContent.length > 60) {
      newErrors.headerContent = 'El encabezado no puede exceder 60 caracteres';
    }

    // Validar footer
    if (formData.footerText.length > 60) {
      newErrors.footerText = 'El pie de pagina no puede exceder 60 caracteres';
    }

    // Validar botones
    if (formData.buttons.length > 0) {
      const invalidButtons = formData.buttons.filter(btn => !btn.text || btn.text.length > 25);
      if (invalidButtons.length > 0) {
        newErrors.buttons = 'Todos los botones deben tener texto (max 25 caracteres)';
      }

      const urlButtons = formData.buttons.filter(btn => btn.type === 'URL');
      const invalidUrlButtons = urlButtons.filter(btn => !btn.url);
      if (invalidUrlButtons.length > 0) {
        newErrors.buttons = 'Los botones URL requieren una URL valida';
      }

      const phoneButtons = formData.buttons.filter(btn => btn.type === 'PHONE_NUMBER');
      const invalidPhoneButtons = phoneButtons.filter(btn => !btn.phone_number);
      if (invalidPhoneButtons.length > 0) {
        newErrors.buttons = 'Los botones de llamada requieren un numero de telefono';
      }
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    await onSubmit(formData);
    handleClose();
  };

  const handleClose = () => {
    setFormData({
      name: '',
      lineId: '',
      content: '',
      variables: [],
      category: 'UTILITY',
      language: 'es',
      headerType: 'NONE',
      headerContent: '',
      headerExample: null,
      headerCaption: '',
      headerFilename: '',
      footerText: '',
      buttons: []
    });
    setCharCount(0);
    setHeaderCharCount(0);
    setFooterCharCount(0);
    setErrors({});
    setUploadedFile(null);
    setUploadError(null);
    setUploadingFile(false);
    onHide();
  };

  const insertVariable = (varName) => {
    const varIndex = formData.variables.findIndex(v => v.name === varName);
    if (varIndex !== -1 && contentTextareaRef.current) {
      const placeholder = `{{${varIndex + 1}}}`;
      const textarea = contentTextareaRef.current;
      const cursorPos = textarea.selectionStart;
      const textBefore = formData.content.substring(0, cursorPos);
      const textAfter = formData.content.substring(cursorPos);
      const newContent = textBefore + placeholder + textAfter;

      setFormData({ ...formData, content: newContent });
      setCharCount(calculateBodyCharCount(newContent, formData.variables));

      // Posicionar el cursor después de la variable insertada
      setTimeout(() => {
        textarea.focus();
        const newCursorPos = cursorPos + placeholder.length;
        textarea.setSelectionRange(newCursorPos, newCursorPos);
      }, 0);
    }
  };

  // Aplicar formato de texto (negrita, cursiva, tachado, código)
  const applyTextFormat = (formatType) => {
    if (!contentTextareaRef.current) return;

    const textarea = contentTextareaRef.current;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = formData.content.substring(start, end);

    let prefix = '';
    let suffix = '';

    switch (formatType) {
      case 'bold':
        prefix = '*';
        suffix = '*';
        break;
      case 'italic':
        prefix = '_';
        suffix = '_';
        break;
      case 'strikethrough':
        prefix = '~';
        suffix = '~';
        break;
      case 'code':
        prefix = '```';
        suffix = '```';
        break;
      default:
        return;
    }

    const textBefore = formData.content.substring(0, start);
    const textAfter = formData.content.substring(end);
    const formattedText = prefix + selectedText + suffix;
    const newContent = textBefore + formattedText + textAfter;

    setFormData({ ...formData, content: newContent });
    setCharCount(calculateBodyCharCount(newContent, formData.variables));

    // Posicionar el cursor
    setTimeout(() => {
      textarea.focus();
      if (selectedText) {
        // Si había texto seleccionado, seleccionar el texto formateado
        textarea.setSelectionRange(start + prefix.length, end + prefix.length);
      } else {
        // Si no había selección, posicionar cursor entre los marcadores
        const newCursorPos = start + prefix.length;
        textarea.setSelectionRange(newCursorPos, newCursorPos);
      }
    }, 0);
  };

  // Insertar emoji en la posición del cursor
  const insertEmoji = (emojiData) => {
    if (!contentTextareaRef.current) return;

    const textarea = contentTextareaRef.current;
    const cursorPos = textarea.selectionStart;
    const textBefore = formData.content.substring(0, cursorPos);
    const textAfter = formData.content.substring(cursorPos);
    const newContent = textBefore + emojiData.emoji + textAfter;

    setFormData({ ...formData, content: newContent });
    setCharCount(calculateBodyCharCount(newContent, formData.variables));

    // Posicionar el cursor después del emoji
    setTimeout(() => {
      textarea.focus();
      const newCursorPos = cursorPos + emojiData.emoji.length;
      textarea.setSelectionRange(newCursorPos, newCursorPos);
    }, 0);

    setShowEmojiPicker(false);
  };

  // Cerrar emoji picker al hacer clic fuera
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (emojiPickerRef.current && !emojiPickerRef.current.contains(event.target)) {
        setShowEmojiPicker(false);
      }
    };

    if (showEmojiPicker) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showEmojiPicker]);

  // Parsear formato de WhatsApp para vista previa
  const parseWhatsAppFormatting = useCallback((text) => {
    if (!text) return null;

    // Escapar HTML primero
    let html = text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');

    // Aplicar formato de código primero (```texto```)
    html = html.replace(/```([^`]+)```/g, '<code class="wa-code">$1</code>');

    // Negrita (*texto*)
    html = html.replace(/\*([^*]+)\*/g, '<strong class="wa-bold">$1</strong>');

    // Cursiva (_texto_)
    html = html.replace(/_([^_]+)_/g, '<em class="wa-italic">$1</em>');

    // Tachado (~texto~)
    html = html.replace(/~([^~]+)~/g, '<del class="wa-strikethrough">$1</del>');

    // Reemplazar variables {{1}}, {{2}}, etc. con estilo
    html = html.replace(/\{\{(\d+)\}\}/g, '<span class="wa-variable">{{$1}}</span>');

    // Preservar saltos de línea
    html = html.replace(/\n/g, '<br />');

    return html;
  }, []);

  // Generar contenido con ejemplos para la vista previa
  const getPreviewContent = useCallback(() => {
    let content = formData.content;
    formData.variables.forEach((variable, index) => {
      const placeholder = `{{${index + 1}}}`;
      const exampleValue = variable.example || `[${variable.name || `Variable ${index + 1}`}]`;
      content = content.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), exampleValue);
    });
    return content;
  }, [formData.content, formData.variables]);

  if (!show) return null;

  return (
    <div className="template-editor-page">
      {/* Header */}
      <div className="template-editor-header">
        <div className="template-editor-header-left">
          <button type="button" className="template-back-btn" onClick={handleClose}>
            <i className="bi bi-arrow-left"></i>
          </button>
          <h1 className="template-editor-title">
            {template ? 'Editar plantilla' : 'Crear plantilla de mensaje'}
          </h1>
        </div>
        <div className="template-editor-header-actions">
          <Button variant="outline-dark" onClick={handleClose} className="template-btn-cancel" disabled={loading}>
            Cancelar
          </Button>
          <Button variant="primary" onClick={handleSubmit} className="template-btn-submit" disabled={loading}>
            {loading ? (
              <>
                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                {template ? 'Actualizando...' : 'Enviando...'}
              </>
            ) : (
              <>
                {template ? 'Actualizar' : 'Enviar a Meta'}
                <i className="bi bi-send ms-2"></i>
              </>
            )}
          </Button>
        </div>
      </div>

      {/* Main content */}
      <div className="template-editor-content">
        {/* Left panel - Form */}
        <div className="template-editor-form-panel">
          <div className="template-editor-form-scroll">
            <Form onSubmit={handleSubmit}>
              {/* Informacion basica */}
              <div className="template-form-section">
                <h3 className="template-form-section-title">Información básica</h3>
                <Row className="mb-3">
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="template-label">Nombre <small className="text-muted">(snake_case)</small></Form.Label>
                      <Form.Control
                        type="text"
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        placeholder="saludo_bienvenida"
                        className="template-input"
                        isInvalid={!!errors.name}
                      />
                      <Form.Control.Feedback type="invalid">{errors.name}</Form.Control.Feedback>
                    </Form.Group>
                  </Col>
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="template-label">Línea de WhatsApp</Form.Label>
                      <Form.Select
                        value={formData.lineId}
                        onChange={(e) => setFormData({ ...formData, lineId: e.target.value })}
                        className="template-input"
                        isInvalid={!!errors.lineId}
                      >
                        <option value="">Seleccione una línea</option>
                        {lines.map(line => (
                          <option key={line.id} value={line.id}>
                            {line.company_name} - {line.phone_number}
                          </option>
                        ))}
                      </Form.Select>
                      <Form.Control.Feedback type="invalid">{errors.lineId}</Form.Control.Feedback>
                    </Form.Group>
                  </Col>
                </Row>

                <Row className="mb-3">
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="template-label">Categoría</Form.Label>
                      <Form.Select
                        value={formData.category}
                        onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                        className="template-input"
                      >
                        <option value="UTILITY">Utilidad (Transaccional)</option>
                        <option value="MARKETING">Marketing (Promocional)</option>
                        <option value="AUTHENTICATION">Autenticación (OTP)</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                  <Col md={6}>
                    <Form.Group>
                      <Form.Label className="template-label">Idioma</Form.Label>
                      <Form.Select
                        value={formData.language}
                        onChange={(e) => setFormData({ ...formData, language: e.target.value })}
                        className="template-input"
                      >
                        <option value="es">Español</option>
                        <option value="en">Inglés</option>
                        <option value="pt_BR">Portugués (Brasil)</option>
                        <option value="es_AR">Español (Argentina)</option>
                        <option value="es_MX">Español (México)</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                </Row>
              </div>

              {/* Pestanas para componentes */}
              <div className="template-form-section">
                <h3 className="template-form-section-title">Contenido del mensaje</h3>
                <Tabs activeKey={activeTab} onSelect={(k) => setActiveTab(k)} className="template-tabs mb-3">
                  <Tab eventKey="header" title="Encabezado">
                    <Card className="template-tab-card">
                      <Form.Group className="mb-3">
                        <Form.Label>Tipo de encabezado</Form.Label>
                        <Form.Select
                          value={formData.headerType}
                          onChange={(e) => setFormData({ ...formData, headerType: e.target.value })}
                        >
                          <option value="NONE">Sin encabezado</option>
                          <option value="TEXT">Texto</option>
                          <option value="IMAGE">Imagen</option>
                          <option value="VIDEO">Video</option>
                          <option value="DOCUMENT">Documento</option>
                        </Form.Select>
                      </Form.Group>

                      {formData.headerType === 'TEXT' && (
                        <Form.Group>
                          <Form.Label>Texto del encabezado</Form.Label>
                          <Form.Control
                            type="text"
                            value={formData.headerContent}
                            onChange={handleHeaderChange}
                            placeholder="Ej: Confirmación de pedido #{{1}}"
                            maxLength={60}
                            isInvalid={!!errors.headerContent}
                          />
                          <Form.Text className="text-muted">
                            {headerCharCount}/60 caracteres. Usa {'{{1}}'} para variables.
                          </Form.Text>
                          <Form.Control.Feedback type="invalid">{errors.headerContent}</Form.Control.Feedback>
                        </Form.Group>
                      )}

                      {['IMAGE', 'VIDEO', 'DOCUMENT'].includes(formData.headerType) && (
                        <Form.Group>
                          <Form.Label>Archivo del medio</Form.Label>

                          {uploadError && (
                            <Alert variant="danger" className="mb-2">
                              {uploadError}
                            </Alert>
                          )}

                          {!uploadedFile && (
                            <>
                              <Form.Control
                                type="file"
                                onChange={handleFileChange}
                                disabled={uploadingFile || !formData.lineId}
                                accept={
                                  formData.headerType === 'IMAGE' ? 'image/jpeg,image/jpg,image/png' :
                                  formData.headerType === 'VIDEO' ? 'video/mp4,video/3gpp,video/quicktime' :
                                  '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.zip,.rar'
                                }
                              />
                              <Form.Text className="text-muted">
                                {!formData.lineId && 'Primero seleccione una línea de WhatsApp. '}
                                {formData.headerType === 'IMAGE' && 'Formatos: JPG, PNG (max 5MB)'}
                                {formData.headerType === 'VIDEO' && 'Formatos: MP4, 3GPP, MOV (max 16MB)'}
                                {formData.headerType === 'DOCUMENT' && 'Formatos: PDF, Word, Excel, PowerPoint, TXT, CSV, ZIP, RAR (max 100MB)'}
                              </Form.Text>
                            </>
                          )}

                          {uploadingFile && (
                            <div className="d-flex align-items-center mt-2">
                              <Spinner animation="border" size="sm" className="me-2" />
                              <span>Subiendo archivo...</span>
                            </div>
                          )}

                          {uploadedFile && !uploadingFile && (
                            <div className="mt-2 p-3 border rounded bg-light">
                              <div className="d-flex justify-content-between align-items-start">
                                <div>
                                  <div className="d-flex align-items-center mb-2">
                                    <i className={`bi ${
                                      formData.headerType === 'IMAGE' ? 'bi-file-image' :
                                      formData.headerType === 'VIDEO' ? 'bi-file-play' :
                                      'bi-file-earmark-text'
                                    } fs-4 me-2`}></i>
                                    <div>
                                      <strong>{uploadedFile.filename}</strong>
                                      <br />
                                      <small className="text-muted">
                                        {(uploadedFile.size / 1024 / 1024).toFixed(2)} MB
                                        {uploadedFile.handle && ` - Handle: ${uploadedFile.handle}`}
                                      </small>
                                    </div>
                                  </div>
                                  {formData.headerType === 'IMAGE' && uploadedFile.publicUrl && (
                                    <img
                                      src={uploadedFile.publicUrl}
                                      alt="Preview"
                                      style={{ maxWidth: '200px', maxHeight: '150px', objectFit: 'contain' }}
                                      className="mt-2"
                                    />
                                  )}
                                </div>
