   388→        // Si había texto seleccionado, seleccionar el texto formateado
   389→        textarea.setSelectionRange(start + prefix.length, end + prefix.length);
   390→      } else {
   391→        // Si no había selección, posicionar cursor entre los marcadores
   392→        const newCursorPos = start + prefix.length;
   393→        textarea.setSelectionRange(newCursorPos, newCursorPos);
   394→      }
   395→    }, 0);
   396→  };
