   438→  // Parsear formato de WhatsApp para vista previa
   439→  const parseWhatsAppFormatting = useCallback((text) => {
   440→    if (!text) return null;
   441→
   442→    // Escapar HTML primero
   443→    let html = text
   444→      .replace(/&/g, '&amp;')
   445→      .replace(/</g, '&lt;')
   446→      .replace(/>/g, '&gt;');
   447→
   448→    // Aplicar formato de código primero (```texto```)
