   450→
   451→    // Negrita (*texto*)
   452→    html = html.replace(/\*([^*]+)\*/g, '<strong class="wa-bold">$1</strong>');
   453→
   454→    // Cursiva (_texto_)
   455→    html = html.replace(/_([^_]+)_/g, '<em class="wa-italic">$1</em>');
   456→
   457→    // Tachado (~texto~)
   458→    html = html.replace(/~([^~]+)~/g, '<del class="wa-strikethrough">$1</del>');
   459→
   460→    // Reemplazar variables {{1}}, {{2}}, etc. con estilo
   461→    html = html.replace(/\{\{(\d+)\}\}/g, '<span class="wa-variable">{{$1}}</span>');
   462→
   463→    // Preservar saltos de línea
   464→    html = html.replace(/\n/g, '<br />');
   465→
   466→    return html;
   467→  }, []);
