  padding: 12px;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
}

.phone-notch {
  width: 120px;
  height: 24px;
  background: #1C1C1D;
  border-radius: 0 0 16px 16px;
  margin: 0 auto 8px;
}

.phone-screen {
  background: #E5DDD5;
  border-radius: 28px;
  overflow: hidden;
  min-height: 500px;
}

/* WhatsApp Header */
.whatsapp-header {
  background: #075E54;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.wa-header-back {
  color: white;
