  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 16px;
}

.wa-header-info {
  display: flex;
  flex-direction: column;
}

.wa-header-name {
  color: white;
  font-size: 14px;
  font-weight: 600;
}

.wa-header-status {
  color: rgba(255, 255, 255, 0.7);
  font-size: 11px;
}

