}

/* Message Bubble */
.wa-message-bubble {
  background: white;
  border-radius: 8px;
  padding: 8px;
  max-width: 85%;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  position: relative;
}

.wa-message-bubble::before {
  content: '';
  position: absolute;
  left: -8px;
  top: 0;
  border-width: 8px;
  border-style: solid;
  border-color: white transparent transparent transparent;
}

/* Message Header */
.wa-message-header-text {
  font-size: 14px;
  font-weight: 600;
  color: #1C1C1D;
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid #E5E5EA;
}

/* Message Media */
.wa-message-media {
  width: 100%;
  height: 150px;
  background: #F2F2F7;
  border-radius: 6px;
  margin-bottom: 8px;
  overflow: hidden;
}

.wa-message-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.wa-media-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #909093;
}

.wa-media-placeholder i {
  font-size: 32px;
  margin-bottom: 8px;
}

.wa-media-placeholder span {
  font-size: 12px;
}

/* Document */
.wa-message-document {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px;
  background: #F2F2F7;
  border-radius: 6px;
  margin-bottom: 8px;
}

.wa-message-document i {
  font-size: 24px;
  color: #dc3545;
}

.wa-message-document span {
  font-size: 12px;
  color: #4D4D4F;
  word-break: break-all;
}

/* Message Body */
.wa-message-body {
  font-size: 14px;
  line-height: 1.4;
  color: #1C1C1D;
  word-wrap: break-word;
  white-space: pre-wrap;
}

.wa-message-body .wa-placeholder {
  color: #909093;
  font-style: italic;
}

.wa-message-body .wa-bold {
  font-weight: 700;
}

.wa-message-body .wa-italic {
  font-style: italic;
}

.wa-message-body .wa-strikethrough {
  text-decoration: line-through;
}

.wa-message-body .wa-code {
  font-family: monospace;
  background-color: #F2F2F7;
  padding: 2px 4px;
  border-radius: 3px;
  font-size: 12px;
}

.wa-message-body .wa-variable {
  background-color: #FFF3CD;
  color: #856404;
  padding: 1px 4px;
  border-radius: 3px;
  font-weight: 500;
  font-size: 12px;
}

/* Message Footer */
.wa-message-footer {
  font-size: 11px;
  color: #909093;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid #E5E5EA;
}

/* Message Timestamp */
.wa-message-time {
  font-size: 10px;
  color: #909093;
  text-align: right;
  margin-top: 4px;
}

/* Buttons Container */
.wa-buttons-container {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.wa-button {
  background: white;
  border: none;
  border-radius: 8px;
  padding: 10px 12px;
  text-align: center;
  font-size: 14px;
  color: #00A5F4;
  font-weight: 500;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Responsive */
@media (max-width: 992px) {
  .template-editor-content {
    flex-direction: column;
  }

  .template-editor-form-panel {
    max-width: 100%;
    border-right: none;
    border-bottom: 1px solid #E5E5EA;
  }

  .template-editor-preview-panel {
    padding: 16px;
  }

  .phone-frame {
    width: 280px;
  }
}

@media (max-width: 576px) {
  .template-editor-header {
    flex-direction: column;
    gap: 12px;
    padding: 12px 16px;
  }

  .template-editor-header-left {
    width: 100%;
  }

  .template-editor-header-actions {
    width: 100%;
    justify-content: flex-end;
  }

  .template-editor-form-scroll {
    padding: 16px;
  }

  .template-editor-title {
    font-size: 16px;
  }

  .phone-frame {
    width: 100%;
    max-width: 300px;
  }

  .emoji-picker-dropdown {
    left: 50%;
    transform: translateX(-50%);
    width: calc(100vw - 48px);
    max-width: 320px;
  }
}

