/* Template Editor Page - Full Page Layout */

.template-editor-page {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #F7F8FA;
  z-index: 1050;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Header */
.template-editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background-color: #fff;
  border-bottom: 1px solid #E5E5EA;
  flex-shrink: 0;
}

.template-editor-header-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.template-back-btn {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: none;
  background-color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background-color 0.2s;
}

.template-back-btn:hover {
  background-color: #F2F2F7;
}

.template-back-btn i {
  font-size: 20px;
  color: #1C1C1D;
}

.template-editor-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 20px;
  line-height: 28px;
  color: #1C1C1D;
  margin: 0;
}

.template-editor-header-actions {
  display: flex;
  gap: 12px;
}

.template-btn-cancel {
  height: 40px;
  padding: 0 20px;
  border: 1px solid #1C1C1D;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  color: #1C1C1D;
  background: white;
}

.template-btn-cancel:hover {
  background-color: #F2F2F7;
  border-color: #1C1C1D;
  color: #1C1C1D;
}

.template-btn-submit {
  height: 40px;
  padding: 0 20px;
  background-color: #FEBF1D;
  border: none;
  border-radius: 8px;
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 14px;
  color: #1C1C1D;
  display: flex;
  align-items: center;
  gap: 8px;
}

.template-btn-submit:hover {
  background-color: #e0a819;
  color: #1C1C1D;
}

.template-btn-submit:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

/* Main Content Area */
.template-editor-content {
  display: flex;
  flex: 1;
  overflow: hidden;
}

/* Left Panel - Form */
.template-editor-form-panel {
  flex: 2;
  min-width: 0;
  background-color: #fff;
  border-right: 1px solid #E5E5EA;
  display: flex;
  flex-direction: column;
}

.template-editor-form-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
}

.template-form-section {
  margin-bottom: 32px;
}

.template-form-section-title {
  font-family: 'Lato', sans-serif;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  color: #1C1C1D;
  margin-bottom: 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid #E5E5EA;
}

/* Form inputs */
.template-label {
  font-family: 'Lato', sans-serif;
  font-weight: 600;
  font-size: 12px;
  line-height: 16px;
  color: #4D4D4F;
  margin-bottom: 8px;
  letter-spacing: 0.06px;
}

.template-input,
.template-textarea {
  font-family: 'Lato', sans-serif;
  font-weight: 500;
  font-size: 14px;
  line-height: 20px;
  color: #4D4D4F;
  border: 1px solid #909093;
  border-radius: 8px;
  padding: 10px 12px;
}

.template-input:focus,
.template-textarea:focus {
  border-color: #FEBF1D;
  box-shadow: 0 0 0 0.2rem rgba(254, 191, 29, 0.25);
}

